create schema if not exists ged;
create table if not exists ged.fiscal_portal_publication(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,fiscalization_period_id uuid not null,publication_number varchar(40) not null,access_token_hash text null,access_mode varchar(40) not null default 'AUTHENTICATED',status varchar(40) not null default 'DRAFT',published_by uuid null,published_at timestamptz null,expires_at timestamptz null,revoked_by uuid null,revoked_at timestamptz null,revoke_reason text null,fiscal_user_id uuid null,fiscal_name text null,fiscal_email text null,notes text null,viewed_at timestamptz null,decided_at timestamptz null,reg_status char(1) not null default 'A');
alter table ged.fiscal_portal_publication add column if not exists viewed_at timestamptz null;
alter table ged.fiscal_portal_publication add column if not exists decided_at timestamptz null;
create table if not exists ged.fiscal_portal_manifestation(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,publication_id uuid not null references ged.fiscal_portal_publication(id),fiscalization_period_id uuid not null,manifestation_type varchar(40) not null,decision varchar(40) not null,comments text null,submitted_by uuid null,submitted_name text null,submitted_email text null,submitted_at timestamptz not null default now(),ip_address inet null,user_agent text null,payload_json jsonb null,reg_status char(1) not null default 'A');
create table if not exists ged.fiscal_acceptance_signature(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,publication_id uuid not null references ged.fiscal_portal_publication(id),fiscalization_period_id uuid not null,signature_type varchar(40) not null default 'ELECTRONIC',signer_user_id uuid null,signer_name text not null,signer_email text null,signer_document text null,signed_at timestamptz not null default now(),ip_address inet null,user_agent text null,signed_hash_sha256 text not null,signed_payload_json jsonb not null,certificate_subject text null,certificate_serial_number text null,certificate_issuer text null,certificate_valid_from timestamptz null,certificate_valid_to timestamptz null,validation_status varchar(40) null,reg_status char(1) not null default 'A');
create table if not exists ged.fiscal_portal_event(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,publication_id uuid null,fiscalization_period_id uuid not null,event_type varchar(80) not null,event_title text not null,event_description text null,from_status varchar(40) null,to_status varchar(40) null,performed_by uuid null,performed_name text null,performed_at timestamptz not null default now(),ip_address inet null,user_agent text null,payload_json jsonb null,reg_status char(1) not null default 'A');
create unique index if not exists ux_fiscal_portal_publication_tenant_number on ged.fiscal_portal_publication(tenant_id,publication_number);
create index if not exists ix_fiscal_portal_publication_period on ged.fiscal_portal_publication(tenant_id,fiscalization_period_id,status);
create index if not exists ix_fiscal_portal_manifestation_publication on ged.fiscal_portal_manifestation(tenant_id,publication_id,submitted_at desc);
create unique index if not exists ux_fiscal_acceptance_signature_publication on ged.fiscal_acceptance_signature(tenant_id,publication_id) where reg_status='A';
create index if not exists ix_fiscal_acceptance_signature_period on ged.fiscal_acceptance_signature(tenant_id,fiscalization_period_id,signed_at desc);
create index if not exists ix_fiscal_portal_event_period on ged.fiscal_portal_event(tenant_id,fiscalization_period_id,performed_at desc);
